    return float(x)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Calculate factorial
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i

    # Apply modulo
    result = factorial % mod

    return float(result)

scripts.sum_integer_division:
def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']

    total = 0
    for i in range(len(a)):
        quotient = a[i] // b[i]
        total += quotient
        print(f"Position {i}: {a[i]} // {b[i]} = {quotient}")

    print(f"Total sum: {total}")
    return float(total)

